function downloadHTML(){const clone=document.documentElement.cloneNode(true);clone.querySelectorAll('dialog').forEach(n=>n.removeAttribute('open'));clone.querySelectorAll('.open').forEach(n=>n.classList.remove('open'));clone.querySelector('#search').setAttribute('value','');const code=clone.querySelector('script');code.textContent=code.textContent.replace(/const DATA = [\s\S]*?;\nconst \$/,()=> 'const DATA = '+JSON.stringify(DATA).replaceAll('<','\\u003c')+';\nconst $');const b=new Blob(['<!doctype html>\n'+clone.outerHTML],{type:'text/html'});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='Elysian-Stellar-Atlas.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
